unit.function:
def make_reader(raw):
    def read():
        return raw.strip()
    return read

def BenchmarkTest00001(request):
    origin_value = request.META.get('HTTP_ORIGIN', '')
    reader = make_reader(origin_value)
    data = reader()
    digest = hashlib.md5(str(data).encode()).hexdigest()
    return JsonResponse({'digest': str(digest)}, status=200)

